//! Spell "extra" proc lines.
//!
//! `ProcLine::read` (27596 B at `0x101bc5568`) parses the Lich spell-extras
//! TSV. Recovered evidence: the `#{target}` placeholder literal, `f32::from_str`
//! for the duration column, a `Regex::new` over the `[...]` message, and rows
//! shaped like
//! `debuff\topponent\t13\t\tsilenced\tWarding, CS 431-437.`
//! (from the data header `"# Generated by tools/extract_spell_extras.rb from
//! Lich's data/effect-*.dat"`).

use hydra_protocol::runs::Runs;

/// One proc line.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct ProcLine {
    /// The effect kind (`debuff`, `buff`, …).
    pub kind: String,
    /// Who it lands on (`opponent`, `self`, …).
    pub affects: String,
    /// Duration in seconds, when numeric.
    pub duration: Option<f32>,
    /// The status/effect it applies.
    pub status: Option<String>,
    /// Free-text note (`Warding, CS 431-437.`).
    pub note: String,
}

impl ProcLine {
    /// @0x0000000101bc5568 (27596 B)
    pub fn read(line: &str) -> Option<ProcLine> {
        let line = line.trim_end_matches('\r');
        if line.is_empty() || line.starts_with('#') {
            return None;
        }
        let cells: Vec<&str> = line.split('\t').collect();
        if cells.len() < 2 {
            return None;
        }
        let kind = cells[0].trim().to_string();
        if kind.is_empty() {
            return None;
        }
        Some(ProcLine {
            kind,
            affects: cells.get(1).map(|c| c.trim().to_string()).unwrap_or_default(),
            duration: cells.get(2).and_then(|c| c.trim().parse::<f32>().ok()),
            status: cells
                .get(4)
                .map(|c| c.trim())
                .filter(|c| !c.is_empty())
                .map(|c| c.to_string())
                .or_else(|| cells.get(3).map(|c| c.trim()).filter(|c| !c.is_empty()).map(str::to_string)),
            note: cells.last().map(|c| c.trim().to_string()).unwrap_or_default(),
        })
    }

    /// @0x0000000101bc5568 — the run-based entry point.
    pub fn read_runs(runs: &Runs) -> Option<ProcLine> {
        ProcLine::read(&runs.plain())
    }

    /// Substitute the recovered `#{target}` placeholder.
    pub fn expand(&self, text: &str, target: &str) -> String {
        text.replace("#{target}", target)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_recovered_data_row_parses() {
        let line = "debuff\topponent\t13\t\tsilenced\tWarding, CS 431-437.";
        let proc = ProcLine::read(line).unwrap();
        assert_eq!(proc.kind, "debuff");
        assert_eq!(proc.affects, "opponent");
        assert_eq!(proc.duration, Some(13.0));
        assert_eq!(proc.status.as_deref(), Some("silenced"));
        assert_eq!(proc.note, "Warding, CS 431-437.");
    }

    #[test]
    fn comments_and_blank_lines_are_skipped() {
        assert!(ProcLine::read("# Generated by tools/extract_spell_extras.rb").is_none());
        assert!(ProcLine::read("").is_none());
        assert!(ProcLine::read("single-column").is_none());
    }

    #[test]
    fn non_numeric_duration_is_none() {
        let proc = ProcLine::read("buff\tself\tuntil killed\t\t".to_string().as_str()).unwrap();
        assert_eq!(proc.duration, None);
    }

    #[test]
    fn target_placeholder_expands() {
        let proc = ProcLine {
            kind: "debuff".into(),
            ..ProcLine::default()
        };
        assert_eq!(proc.expand("#{target} is silenced", "a kobold"), "a kobold is silenced");
    }
}
